from dates import parse_date
cases = {"2024-1-5": (2024,1,5), "2024-01-05": (2024,1,5), "2024-1-15": (2024,1,15), "2023-12-5": (2023,12,5),
         "1999-10-31": (1999,10,31), "2024-01-5": (2024,1,5), "2024-1-05": (2024,1,5), "2000-02-29": (2000,2,29), "2021-11-09": (2021,11,9)}
for s, exp in cases.items():
    r = parse_date(s)
    assert tuple(r) == exp and all(type(x) is int for x in r), (s, r)
for bad in ["hello", "", "2024-01", "abcd-ef-gh"]:
    try:
        parse_date(bad)
    except ValueError:
        continue
    raise AssertionError("no ValueError for %r" % bad)
print("ok")
